public static String buildMessage(Locale locale, Localizable general, Localizable specific, Object... arguments) {
    final StringBuilder sb = new StringBuilder();

    if (general != null) {
        final MessageFormat generalFmt = new MessageFormat(general.getLocalizedString(locale), locale);
        sb.append(generalFmt.format(arguments));
    }

    if (specific != null) {
        if (sb.length() > 0) {
            sb.append(" ");
